/// Transient Scene View presentation mode; never persisted into scene content.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum SceneViewDimension {
    /// Perspective 3D authoring view.
    #[default]
    ThreeD,
    /// Orthographic XY Native 2D authoring view.
    TwoD,
}

#[derive(Debug, Clone)]
struct EditorViewCamera2d {
    center: Vec3,
    orthographic_height: f32,
}

impl Default for EditorViewCamera2d {
    fn default() -> Self {
        Self {
            center: Vec3::ZERO,
            orthographic_height: 10.0,
        }
    }
}

impl EditorViewCamera2d {
    fn reset(&mut self) {
        *self = Self::default();
    }

    fn focus_on(&mut self, target: Vec3) {
        self.center.x = target.x;
        self.center.y = target.y;
        self.orthographic_height = 8.0;
    }

    fn eye(&self) -> Vec3 {
        Vec3::new(self.center.x, self.center.y, 10.0)
    }

    fn to_transform(&self) -> Transform {
        Transform::from_translation(self.eye())
    }

    fn handle_input(&mut self, response: &egui::Response) {
        let delta = response.ctx.input(|input| input.pointer.delta());
        if response.dragged_by(egui::PointerButton::Middle)
            || response.dragged_by(egui::PointerButton::Secondary)
        {
            let world_per_pixel = self.orthographic_height / response.rect.height().max(1.0);
            self.center.x -= delta.x * world_per_pixel;
            self.center.y += delta.y * world_per_pixel;
        }
        let scroll = if response.hovered() {
            response.ctx.input(|input| input.smooth_scroll_delta.y)
        } else {
            0.0
        };
        if scroll == 0.0 {
            return;
        }
        let pointer = response
            .ctx
            .pointer_hover_pos()
            .unwrap_or_else(|| response.rect.center());
        let offset = pointer - response.rect.center();
        let before_scale = self.orthographic_height / response.rect.height().max(1.0);
        let before = Vec3::new(
            self.center.x + offset.x * before_scale,
            self.center.y - offset.y * before_scale,
            0.0,
        );
        self.orthographic_height =
            (self.orthographic_height * (1.0 - scroll * 0.002)).clamp(0.05, 10_000.0);
        let after_scale = self.orthographic_height / response.rect.height().max(1.0);
        let after = Vec3::new(
            self.center.x + offset.x * after_scale,
            self.center.y - offset.y * after_scale,
            0.0,
        );
        self.center += before - after;
    }

    fn view_projection(&self, viewport: [u32; 2]) -> Mat4 {
        let camera = engine::Camera2d {
            orthographic_height: self.orthographic_height,
            ..engine::Camera2d::default()
        };
        camera
            .view_projection_matrix(&self.to_transform(), viewport)
            .unwrap_or(Mat4::IDENTITY)
    }
}

